{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Coptisine, a quaternary protoberberine with two methylenedioxy groups and no methoxy substituents, was detected in mouse brain homogenates by LC-MS/MS after systemic administration, directly demonstrating BBB crossing for the closest structural analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Berberrubine, a closely related quaternary protoberberine, reached 37.44 ng/mL in rat CSF after systemic exposure, showing meaningful CNS access despite a permanent positive charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Demethyleneberberine reached 267.56 ng/g in rat brain after oral dosing, confirming that quaternary protoberberine alkaloids can distribute into brain tissue at pharmacologically relevant concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Palmatine, another quaternary protoberberine, was detected in rat CSF after systemic administration, supporting class-level BBB permeability for this scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a quaternary protoberberine-like alkaloid with two methylenedioxy groups and an N-methyl group. Although passive diffusion is expected to be poor due to the permanent positive charge, multiple high-transfer experimental analogues—coptisine, berberrubine, demethyleneberberine, and palmatine—are directly detected in brain or CSF after systemic dosing. These direct measurements override the physicochemical prior and support meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma ratio or unbound brain concentration is available for the exact query molecule.",
    "The N-methyl group differs from the closest analogue coptisine and could alter transporter interactions, though it does not remove the shared quaternary protoberberine phenotype.",
    "Efflux transporter involvement was not directly measured, but the consistent brain/CSF detection across analogues indicates adequate net CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

